    private static function digitalWorkshop(): string
    {
        return implode("\n", [
            EditorialBlocks::paragraph(__('Цифровая мастерская начинается с небольшого полезного инструмента. Например, с каталога домашних вещей: название, место хранения и короткая заметка. Такой проект помогает освоить устройство интерфейса и работу с данными без сложной инфраструктуры. Его результат легко проверить: нужная вещь находится за несколько секунд, а записи остаются доступны после закрытия страницы.', 'imperial-future'), true),
            EditorialBlocks::heading(__('Начни с одного обычного действия', 'imperial-future')),
            EditorialBlocks::paragraph(__('Опиши не устройство программы, а свой будущий вечер: открыть каталог, найти паяльник и понять, в какой коробке он лежит. От этого действия легко перейти к минимальным полям и нужной кнопке поиска. Учёт расходов, совместный доступ и распознавание фотографий пока не нужны. Запиши их отдельно, чтобы интересная идея не меняла задачу посреди работы.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Сразу реши, где останутся записи после закрытия страницы. Локальное хранение в браузере подходит для учебного опыта, но не обещает сохранность при очистке профиля. Файл или база требуют другого способа запуска и отдельной копии. Запиши выбранный способ хранения и условия, при которых данные могут исчезнуть.', 'imperial-future')),
            EditorialBlocks::heading(__('Подготовь безопасный материал', 'imperial-future')),
            EditorialBlocks::paragraph(__('Первые записи сделай вымышленными. Не используй фотографии документов, адреса знакомых или настоящие ключи от сервисов ради демонстрации. Если программа читает папку проекта, проверь, какие файлы ей доступны. Конфигурация с паролями не должна попадать в общедоступный каталог.', 'imperial-future')),
            EditorialBlocks::paragraph(__('До первой правки сохрани рабочее состояние привычным способом. Это может быть история версий или заранее подготовленный архив. Важно не название инструмента, а возможность вернуться к известному состоянию и понять, что именно изменилось. Не используй единственную папку с важными данными как площадку для обучения.', 'imperial-future')),
            EditorialBlocks::heading(__('Задание должно помещаться на одну страницу', 'imperial-future')),
            EditorialBlocks::listing([
                __('Каталог открывается на компьютере и телефоне без обязательной регистрации.', 'imperial-future'),
                __('У записи есть название, место хранения и необязательная заметка.', 'imperial-future'),
                __('Поиск находит запись по названию; пустая выдача понятна без объяснений.', 'imperial-future'),
                __('После перезапуска записи сохраняются выбранным способом.', 'imperial-future'),
                __('Экспорт позволяет сохранить записи отдельным файлом.', 'imperial-future'),
            ]),
            EditorialBlocks::paragraph(__('Отложи функции, которые не нужны для повседневного поиска вещей. Платежи, несколько серверов и сложная регистрация увеличивают объём работы, но не помогают найти паяльник. Сначала сделай небольшой законченный инструмент, затем решай, чего действительно не хватает.', 'imperial-future')),
            EditorialBlocks::heading(__('Проверяй после каждого небольшого изменения', 'imperial-future')),
            EditorialBlocks::paragraph(__('Сначала добейся открытия страницы. Затем добавления одной записи. После этого проверь сохранение и только потом поиск. Меняя всё сразу, трудно отличить новую ошибку от старой. Оценивай результат через действие пользователя: созданная запись должна быть видна после повторного открытия.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Обязательно попробуй неудобные данные: длинное название, пробелы вместо текста и две одинаковые записи. Нажми сохранение дважды. Закрой страницу, снова открой её и сравни результат. Если предусмотрен экспорт, открой полученный файл отдельно. Сообщение об успехе ещё не доказывает, что внутри находятся нужные сведения.', 'imperial-future')),
            EditorialBlocks::quote(__('Хороший инструмент не требует веры в обещания. Его результат можно проверить.', 'imperial-future')),
            EditorialBlocks::heading(__('Оставь себе понятный рабочий результат', 'imperial-future')),
            EditorialBlocks::paragraph(__('В конце запиши, как запускается проект, где лежат данные и как восстановить сохранённую версию. Убери временные примеры, сохрани рабочий архив и проверь экспорт. Небольшой инструмент готов, когда основной сценарий повторяется без дополнительных подсказок.', 'imperial-future')),
            EditorialBlocks::paragraph(__('После этого выбери одно улучшение, которое действительно заметишь в работе. Например, быстрый фильтр по коробке. Следующий шаг должен опираться на опыт использования. Первый проект учит удерживать задачу, сохранять результат и отличать работающую функцию от красивого описания.', 'imperial-future')),
        ]);
    }

    private static function independentArchive(): string
    {
        return implode("\n", [
            EditorialBlocks::paragraph(__('Проверку резервной копии удобно начать с простого вопроса: что останется, если завтра исчезнет рабочая папка? Не компьютер вообще, а конкретные документы, фотографии или заметки. Ответ «они ещё в облаке» требует уточнения. Облако может хранить независимую историю, а может быстро повторять каждое удаление. Пока это не проверено, перед нами удобный доступ к файлам, но ещё не понятный план восстановления.', 'imperial-future'), true),
            EditorialBlocks::heading(__('Составь короткую карту потерь', 'imperial-future')),
            EditorialBlocks::paragraph(__('Выдели данные, которые нельзя просто скачать заново: семейные фотографии, собственные тексты, рабочие проекты и настройки, на которые ушло время. Не обязательно начинать со всего диска. Маленький проверенный архив важнее огромной копии, из которой никто не умеет извлечь нужную папку. Для каждой группы запиши место хранения и допустимую потерю последних изменений.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Документ, который меняется каждый день, и завершённый фотоальбом требуют разного расписания. Одному полезны частые версии, другому достаточно новой копии после пополнения. Если приложение хранит всё в своей базе, обычная папка может оказаться неполной. Найди штатный экспорт и проверь, входят ли в него вложения, подписи и другие важные части.', 'imperial-future')),
            EditorialBlocks::heading(__('Независимость важнее числа устройств', 'imperial-future')),
            EditorialBlocks::paragraph(__('Второй раздел одного диска не переживёт отказ самого накопителя. Постоянно подключённый внешний диск доступен тем же программам, что и рабочая папка. Два устройства в одной сумке могут потеряться вместе. Поэтому полезно разделять не только экземпляры, но и причины, по которым они могут одновременно исчезнуть.', 'imperial-future')),
            EditorialBlocks::listing([
                __('Рабочая версия остаётся там, где ты обычно редактируешь файлы.', 'imperial-future'),
                __('Версионная копия позволяет вернуться к состоянию до незамеченной ошибки.', 'imperial-future'),
                __('Отдельный носитель после копирования отключается от рабочего компьютера.', 'imperial-future'),
                __('Ещё один экземпляр хранится отдельно от основного места и защищён от чужого доступа.', 'imperial-future'),
            ]),
            EditorialBlocks::paragraph(__('Это не обязательный список покупок. Сначала используй доступные средства и выясни, какую угрозу они закрывают. Удалённое хранилище помогает пережить потерю оборудования дома, но зависит от доступа к аккаунту. Отключённый диск уменьшает риск случайной перезаписи, однако сам требует аккуратного хранения и периодической проверки.', 'imperial-future')),
            EditorialBlocks::heading(__('У копии должен быть понятный возраст', 'imperial-future')),
            EditorialBlocks::paragraph(__('Успешное задание копирования ещё не означает, что архив свежий. Посмотри дату последнего завершённого запуска и наличие недавнего файла. Сообщения об ошибках должны попадать туда, где ты их заметишь. Если переполнился диск или закончился доступ к сервису, месяцы зелёного значка на старой копии не помогут восстановить вчерашнюю работу.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Не заменяй единственный старый архив новым вслепую. Сохраняй несколько состояний, чтобы обнаруженная поздно ошибка не стала единственной доступной версией. Срок хранения зависит от ценности данных и объёма носителя. Лучше честно хранить несколько проверенных недель, чем обещать бесконечную историю, которая однажды перестанет помещаться.', 'imperial-future')),
            EditorialBlocks::heading(__('Репетиция восстановления занимает отдельное время', 'imperial-future')),
            EditorialBlocks::listing([
                __('Создай пустую папку вне рабочего каталога и отключи автоматическую синхронизацию для неё.', 'imperial-future'),
                __('Верни один свежий документ, старую фотографию и файл из вложенной папки.', 'imperial-future'),
                __('Открой файлы в соответствующих программах, проверь содержимое и даты.', 'imperial-future'),
                __('Запиши, какой доступ понадобился и сколько времени заняла операция.', 'imperial-future'),
            ], true),
            EditorialBlocks::paragraph(__('Не восстанавливай тест поверх оригинала: иначе сама проверка превращается в риск. Для большого архива сначала достаточно нескольких разных файлов, но важную базу или проект полезно периодически поднимать целиком в отдельной среде. Только так обнаруживаются забытые зависимости: приложение, версия формата, пароль шифрования или отсутствующее вложение.', 'imperial-future')),
            EditorialBlocks::details(__('Что делать с паролем от зашифрованной копии', 'imperial-future'), __('Сохрани способ восстановления отдельно от единственного компьютера. Проверь, что сможешь получить его без рабочей папки и без потерянного телефона. Не записывай секрет рядом с общедоступной копией. Удобство доступа и защита от посторонних требуют отдельного решения, а не одного универсального места для всего.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Хорошая резервная схема заканчивается не архивом с красивым названием, а возвращённым документом. Назначь следующую проверку после заметного изменения устройства, программы или способа хранения. Если восстановление получилось сегодня и его порядок понятен без памяти о прошлой настройке, у тебя уже есть рабочая защита, которую можно постепенно улучшать.', 'imperial-future')),
        ]);
    }

    private static function homeLaboratory(): string
    {
        return implode("\n", [
            EditorialBlocks::paragraph(__('Домашняя лаборатория Docker может начинаться с одного контейнера, который показывает локальную страницу. Её задача не заменить промышленный сервер, а дать место для эксперимента: изменить настройку, увидеть результат и спокойно убрать всё лишнее. Для этого важнее понимать доступ к папкам и портам, чем запускать десяток сервисов из чужой инструкции. В первом опыте обойдёмся без личных данных, базы и доступа из интернета.', 'imperial-future'), true),
            EditorialBlocks::heading(__('Отдели эксперимент от обычной работы', 'imperial-future')),
            EditorialBlocks::paragraph(__('Создай отдельный каталог лаборатории и вложенную папку site. Положи в неё простой index.html с коротким текстом. Не подключай домашний каталог целиком: контейнеру незачем видеть документы, фотографии и ключи. Для публикации статической страницы ему достаточно одной папки, причём только для чтения. Такой небольшой объём доступа проще проверить.', 'imperial-future')),
            EditorialBlocks::paragraph(__('У контейнера есть собственный жизненный цикл. Его можно пересоздать, и изменения внутри его файловой системы при этом могут исчезнуть. Bind mount связывает определённую папку компьютера с путём внутри контейнера. Это удобно для опытов, но означает прямой доступ программы к указанным файлам. Контейнер не превращает любую подключённую папку в безопасную песочницу.', 'imperial-future')),
            EditorialBlocks::heading(__('Начни с короткого Compose-файла', 'imperial-future')),
            EditorialBlocks::code("services:\n  web:\n    image: nginx:stable-alpine\n    ports:\n      - \"127.0.0.1:18080:80\"\n    volumes:\n      - ./site:/usr/share/nginx/html:ro"),
            EditorialBlocks::paragraph(__('Сохрани пример как compose.yaml рядом с папкой site. Адрес 127.0.0.1 ограничивает опубликованный порт самим компьютером. Номер 18080 выбран для опыта; если он занят, возьми другой свободный порт. Метка образа показывает ветку, но не фиксирует неизменные байты. Для повторяемого важного окружения отдельно проверяют и записывают конкретную версию или digest образа.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Запусти docker compose up -d из каталога лаборатории и открой http://127.0.0.1:18080. Если страницы нет, сначала проверь docker compose ps, затем docker compose logs web. Не отключай межсетевой экран и не открывай порты роутера ради локального примера. Ошибка пути или занятый порт решаются на своём уровне, без расширения доступа.', 'imperial-future')),
            EditorialBlocks::heading(__('Измени файл и проверь границы', 'imperial-future')),
            EditorialBlocks::paragraph(__('Отредактируй текст в index.html и обнови страницу. Изменение видно без пересборки образа, потому что сервер читает подключённую папку. Затем пересоздай контейнер и убедись, что текст остался. Он живёт на компьютере, а не только внутри контейнера. Это маленькая, но полезная проверка того, где действительно находятся данные.', 'imperial-future')),
            EditorialBlocks::quote(__('Перезапуск проверяет работу процесса. Пересоздание помогает проверить, где остались файлы.', 'imperial-future')),
            EditorialBlocks::table([__('Действие', 'imperial-future'), __('Что ожидать', 'imperial-future')], [
                ['docker compose stop', __('Контейнер останавливается, его состояние пока остаётся.', 'imperial-future')],
                ['docker compose down', __('Контейнер и сеть проекта удаляются; папка site остаётся.', 'imperial-future')],
                ['docker compose down --volumes', __('Дополнительно удаляются управляемые Compose тома; это не команда обычной остановки.', 'imperial-future')],
            ]),
            EditorialBlocks::heading(__('Добавляй только понятные зависимости', 'imperial-future')),
            EditorialBlocks::paragraph(__('Когда понадобится приложение с базой, сначала выясни штатный способ сохранения и восстановления его данных. Копирование каталога работающей базы не всегда даёт согласованную копию. Используй предусмотренный экспорт или остановку, если этого требует документация. Названный том удобен, но не является резервной копией и может быть удалён командой уборки.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Не подключай Docker socket к случайному сервису и не включай privileged без конкретной причины. Такие настройки существенно расширяют возможности контейнера. Секреты не стоит помещать прямо в публикуемый Compose-файл. Даже учебная лаборатория выигрывает от минимальных прав, понятных образов и короткого списка зависимостей, которые ты действительно используешь.', 'imperial-future')),
            EditorialBlocks::heading(__('Закончи опыт уборкой своего проекта', 'imperial-future')),
            EditorialBlocks::paragraph(__('Останови лабораторию командой docker compose down и проверь, что страница больше не открывается. Папку site оставь для следующего опыта или удали осознанно. Не запускай глобальную очистку Docker на компьютере, где есть другие проекты: чужой неактивный ресурс может быть нужен. Хорошая лаборатория оставляет понятный результат, понятные данные и понятный способ всё остановить.', 'imperial-future')),
            EditorialBlocks::source(__('Документация Docker: подключение папок с помощью bind mounts', 'imperial-future'), 'https://docs.docker.com/engine/storage/bind-mounts/'),
        ]);
    }

    private static function accessKeys(): string
    {
        return implode("\n", [
            EditorialBlocks::paragraph(__('Предложение создать ключ доступа выглядит как удобная замена паролю: подтвердил вход на телефоне и продолжил работу. Но выбирать способ входа лучше вместе со способом восстановления. Пока не понятно, как попасть в аккаунт без основного устройства, новая кнопка решает только половину задачи. Разберём переход без обещаний, что пароли исчезнут к определённой дате или что одна технология закроет все угрозы.', 'imperial-future'), true),
            EditorialBlocks::heading(__('Что именно меняется при входе', 'imperial-future')),
            EditorialBlocks::paragraph(__('Passkey использует пару ключей. Сервис хранит открытый ключ, а пользователь подтверждает операцию с помощью закрытого, которым управляет его устройство или провайдер учётных данных. Вместо передачи общей секретной строки устройство подписывает запрос. Сам секрет не вводится в форму сайта. Это уменьшает риск, связанный с повторяющимися паролями и их выманиванием через поддельную страницу.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Ключ связан с сервисом, для которого создан. Поддельный домен не получает готовый секрет для входа на настоящий сайт. При этом защита входа не равна защите всего аккаунта: остаются восстановление, уже открытые сеансы, вредоносные программы и действия после авторизации. Поэтому слово «устойчивый к фишингу» не стоит превращать в обещание полной неуязвимости.', 'imperial-future')),
            EditorialBlocks::heading(__('Биометрия не становится паролем сайта', 'imperial-future')),
            EditorialBlocks::paragraph(__('Отпечаток, лицо или PIN обычно разрешают устройству использовать ключ локально. Сайт получает результат криптографической проверки, а не фотографию лица вместо пароля. Но само устройство всё равно нужно блокировать и обновлять. Если посторонний управляет твоим разблокированным компьютером, удобный вход не отменяет этот риск.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Не подтверждай неожиданную операцию только потому, что окно выглядит системным. Сначала убедись, что ты сам начал вход и понимаешь, какой аккаунт открываешь. Не устанавливай программу удалённого доступа по просьбе человека, который предлагает «помочь с ключом». Техническая защита не может компенсировать добровольно переданное управление устройством.', 'imperial-future')),
            EditorialBlocks::heading(__('Выясни, где хранится запасной путь', 'imperial-future')),
            EditorialBlocks::paragraph(__('Некоторые ключи синхронизируются через провайдера учётных данных, другие привязаны к устройству, например отдельному аппаратному ключу. Возможности переноса и восстановления зависят от выбранного решения. Не предполагай, что любой ключ автоматически появится на новом телефоне. Посмотри настройки конкретного сервиса и провайдера до того, как удалять прежний способ входа.', 'imperial-future')),
            EditorialBlocks::listing([
                __('Проверь вход со второго доверенного устройства или другого зарегистрированного ключа.', 'imperial-future'),
                __('Сохрани предусмотренные сервисом резервные коды отдельно от единственного телефона.', 'imperial-future'),
                __('Защити аккаунт провайдера, через которого синхронизируются ключи.', 'imperial-future'),
                __('Уточни, как отозвать потерянное устройство и завершить его открытые сеансы.', 'imperial-future'),
                __('Запиши порядок восстановления без самих секретов в общедоступных заметках.', 'imperial-future'),
            ]),
            EditorialBlocks::heading(__('Пароли остаются частью смешанной схемы', 'imperial-future')),
            EditorialBlocks::paragraph(__('Там, где ключи доступа недоступны или пока не подходят твоему сценарию, используй отдельный пароль для каждого сервиса. Менеджер паролей помогает создавать и хранить такие значения без необходимости помнить их все. Основную почту и само хранилище нужно защищать особенно внимательно: через них часто восстанавливаются остальные аккаунты. Доступный дополнительный фактор также стоит настроить.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Не оставляй одинаковый пароль в нескольких местах под предлогом скорого перехода на новую технологию. Не сохраняй резервные коды только в той же учётной записи, доступ к которой они должны возвращать. При утечке пароля замени его в затронутом сервисе и везде, где он повторялся; затем проверь способы восстановления и открытые сеансы.', 'imperial-future')),
            EditorialBlocks::details(__('Нужно ли сразу удалять старый пароль', 'imperial-future'), __('Не спеши. Сначала проверь новый вход и восстановление на своих устройствах. Затем посмотри, какие методы позволяет отключить конкретный сервис и какие последствия у этого решения. Иногда слабый запасной метод уменьшает пользу сильного основного, но его удаление без рабочего второго пути может просто лишить тебя доступа.', 'imperial-future')),
            EditorialBlocks::heading(__('Переходи по одному аккаунту', 'imperial-future')),
            EditorialBlocks::paragraph(__('Выбери один сервис, настрой ключ и выполни обычный вход заново, не закрывая единственный действующий сеанс до проверки. После успешного опыта подготовь запасной путь и только тогда расширяй схему. Цель не в максимальном количестве новых ключей за вечер. Цель в том, чтобы постороннему стало сложнее войти, а владельцу оставался понятный способ вернуться.', 'imperial-future')),
            EditorialBlocks::source(__('Объяснение ключей доступа от FIDO Alliance', 'imperial-future'), 'https://fidoalliance.org/passkeys/'),
        ]);
    }

    private static function readableInterface(): string
    {
        return implode("\n", [
            EditorialBlocks::paragraph(__('Читаемый интерфейс легче оценивать на конкретной странице, чем по общей красоте макета. Возьмём статью с содержанием, иллюстрацией, формой подписки и обсуждением. Читатель хочет понять тему, найти нужный фрагмент и решить, что делать дальше. Если оформление заставляет сначала разгадывать навигацию, даже хорошая типографика не спасает. Проверим страницу как рабочий маршрут, а не как витрину отдельных декоративных решений.', 'imperial-future'), true),
            EditorialBlocks::heading(__('Сначала порядок, затем выразительность', 'imperial-future')),
            EditorialBlocks::paragraph(__('Заголовок должен называть предмет статьи, а вводный абзац объяснять, какую задачу она поможет решить. После них полезнее показать начало материала, чем несколько экранов украшений. На большой странице подзаголовки работают как указатели: по ним можно восстановить ход мысли, даже если человек пока только просматривает текст.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Рядом с основным текстом не должно быть нескольких одинаково громких приглашений. Выбери главное действие для каждого участка: читать, отправить комментарий или подтвердить подписку. Остальные команды можно оставить доступными, но спокойными. Иерархия нужна не для запрета выбора, а чтобы человек не тратил внимание на расстановку приоритетов вместо тебя.', 'imperial-future')),
            EditorialBlocks::heading(__('Проверяй настоящий текст', 'imperial-future')),
            EditorialBlocks::paragraph(__('Короткие заглушки скрывают проблемы. Подставь длинный русский заголовок, адрес электронной почты, ссылку и фрагмент кода. Проверь узкий экран и увеличенный масштаб браузера. Текст должен переноситься, а элементы управления оставаться доступными. Если ради красивой карточки приходится обрезать важное слово, пересмотри её размеры или порядок содержимого.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Слишком широкую строку трудно удерживать взглядом, слишком тесную приходится часто переносить. Подбирай ширину на живом материале и отдельно смотри списки, таблицы и подписи. Не пытайся сделать весь текст крупнее ради одного слабого заголовка. Плотность страницы складывается из нескольких решений, и исправлять удобнее конкретную причину.', 'imperial-future')),
            EditorialBlocks::heading(__('Подпись кнопки должна обещать действие', 'imperial-future')),
            EditorialBlocks::table([__('Расплывчато', 'imperial-future'), __('Понятнее в своём контексте', 'imperial-future')], [
                [__('Продолжить', 'imperial-future'), __('Отправить комментарий', 'imperial-future')],
                [__('Подробнее', 'imperial-future'), __('Читать о резервных копиях', 'imperial-future')],
                [__('Готово', 'imperial-future'), __('Сохранить настройки', 'imperial-future')],
            ]),
            EditorialBlocks::paragraph(__('Это не универсальный словарь: подпись зависит от результата на конкретном экране. Иконка корзины подходит для знакомой команды удаления, но незнакомый символ без названия заставляет гадать. У кнопок должны быть доступные названия, а у действий с последствиями понятное подтверждение. Человек должен узнавать результат до нажатия, а не после ошибки.', 'imperial-future')),
            EditorialBlocks::heading(__('Ошибка тоже часть страницы', 'imperial-future')),
            EditorialBlocks::paragraph(__('Попробуй отправить форму без обязательного поля и с неверным адресом. Сообщение должно находиться рядом с причиной, объяснять исправление и не стирать уже введённый текст. При успешной отправке нужен столь же заметный результат. Если подтверждение спрятано ниже экрана, человек может нажать кнопку повторно и получить лишнее письмо или комментарий.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Во время ожидания важно не только изменить надпись на кнопке. Состояние должно предотвращать случайное повторение действия и оставаться понятным для клавиатуры и вспомогательных технологий. При сбое сети верни возможность повторить запрос. Не показывай успешный результат только потому, что отправка началась: это разные события.', 'imperial-future')),
            EditorialBlocks::heading(__('Пройди маршрут без мыши', 'imperial-future')),
            EditorialBlocks::listing([
                __('Перемещайся клавишей Tab и следи, виден ли текущий элемент.', 'imperial-future'),
                __('Открой меню и форму, затем попробуй закрыть их обычным ожидаемым действием.', 'imperial-future'),
                __('Проверь порядок фокуса: он должен соответствовать смыслу страницы.', 'imperial-future'),
                __('Убедись, что отличие состояния не передаётся только цветом.', 'imperial-future'),
                __('Повтори основной сценарий с увеличенным масштабом и на телефоне.', 'imperial-future'),
            ]),
            EditorialBlocks::paragraph(__('Для имперской визуальной подачи достаточно выразительного шрифта заголовков, характерной иллюстрации и аккуратных акцентов. Основной текст не обязан имитировать старую печать или говорить архаизмами. Оформление может создавать атмосферу, пока содержание и управление остаются обычными и понятными. Если убрать украшения, хорошая страница всё ещё позволяет прочитать материал, отправить ответ и понять результат.', 'imperial-future')),
            EditorialBlocks::source(__('W3C: простые проверки доступности страницы', 'imperial-future'), 'https://www.w3.org/WAI/test-evaluate/easy-checks/'),
        ]);
    }

    private static function quietTelegraph(): string
    {
        return implode("\n", [
            EditorialBlocks::paragraph(__('Очередь сохранённых статей легко превращается в отдельную работу. В ней соседствуют полезная документация, обсуждения новых инструментов и новости, которые уже ничего не меняют. Информационная гигиена начинается не с запрета читать, а с вопроса: для чего мне этот материал сейчас? Ответ помогает оставить интерес к технологиям и перестать относиться к каждой непрочитанной ссылке как к невыполненному обязательству.', 'imperial-future'), true),
            EditorialBlocks::heading(__('Раздели потоки по назначению', 'imperial-future')),
            EditorialBlocks::paragraph(__('У сообщения об изменении сервиса, которым ты пользуешься, и у обзора необычного устройства разная срочность. Первое может требовать действия, второе достаточно приятно прочитать в свободное время. Если оба попадают в одинаковые уведомления, внимание расходуется ещё до чтения. Отдельный канал для действительно важных сообщений уже уменьшает путаницу.', 'imperial-future')),
            EditorialBlocks::listing([
                __('Срочное: сообщения о доступе, оплате и работе нужных тебе систем.', 'imperial-future'),
                __('Рабочее: документация и материалы для текущей задачи.', 'imperial-future'),
                __('Исследовательское: идеи, которые хочется изучить без обещания внедрения.', 'imperial-future'),
                __('Развлекательное: чтение ради удовольствия, которому не нужен отчёт о пользе.', 'imperial-future'),
            ]),
            EditorialBlocks::paragraph(__('Не обязательно заводить четыре приложения. Достаточно разных папок, фильтров или понятного расписания. Важно не смешивать любопытство с обязательной реакцией. Тогда отключение лишнего уведомления не выглядит как риск пропустить всё на свете: сообщения, от которых действительно зависит работа, остаются отдельно.', 'imperial-future')),
            EditorialBlocks::heading(__('Перед сохранением назови будущую задачу', 'imperial-future')),
            EditorialBlocks::paragraph(__('У ссылки должна быть причина остаться. Например: «нужна при переносе сайта» или «проверить способ восстановления базы». Такая короткая подпись полезнее длинного набора тегов. Если причину трудно назвать, можно прочитать материал сейчас или отпустить его. Возможность найти статью повторно часто стоит меньше, чем постоянное обслуживание огромной коллекции.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Не сохраняй подряд несколько пересказов одного объявления. Оставь первоисточник и, если требуется, один действительно полезный разбор. Для технического решения особенно важны версия, дата и условия применения. Статья может быть написана аккуратно, но относиться к другой версии программы или к среде, которая не похожа на твою.', 'imperial-future')),
            EditorialBlocks::heading(__('Отделяй факт от уверенного тона', 'imperial-future')),
            EditorialBlocks::paragraph(__('В новости об инструменте найди исходное объявление или документацию. Проверь, доступна ли описанная возможность, кому именно и с какими ограничениями. Фразы «все переходят» и «это заменит разработчиков» редко помогают выбрать действие. Полезнее выяснить, какую небольшую задачу можно решить сегодня и сколько стоит проверка этого обещания.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Если источники расходятся, не нужно немедленно выбирать самый убедительный заголовок. Отметь, что пока неизвестно, и отложи решение, если от него ничего не зависит. Для настройки безопасности, совместимости или удаления данных лучше найти точный контракт, чем полагаться на популярность пересказа. Неопределённость бывает нормальным результатом чтения, а не личной недоработкой.', 'imperial-future')),
            EditorialBlocks::quote(__('Не каждая интересная возможность должна становиться следующим проектом.', 'imperial-future')),
            EditorialBlocks::heading(__('Завершай чтение маленьким результатом', 'imperial-future')),
            EditorialBlocks::paragraph(__('После полезной статьи запиши один вывод своими словами. Например: «экспорт этой программы нужно проверять вместе с вложениями». Если материал относится к текущей работе, добавь конкретную проверку в её список задач. Если не относится, не создавай искусственное обязательство. Достаточно понять идею и оставить ссылку там, где её можно найти по причине сохранения.', 'imperial-future')),
            EditorialBlocks::details(__('Что делать с давней очередью «прочитать позже»', 'imperial-future'), __('Просмотри названия и оставь только материалы с понятной текущей причиной. Остальное можно переместить в холодный архив без даты обязательного чтения. Не пытайся компенсировать пропущенные месяцы за один вечер. Очередь должна помогать выбирать, а не доказывать, сколько информации ты ещё не успел обработать.', 'imperial-future')),
            EditorialBlocks::heading(__('Проверь новый режим на обычной неделе', 'imperial-future')),
            EditorialBlocks::paragraph(__('Выбери небольшое окно для чтения вместо постоянного переключения между уведомлениями. В конце недели посмотри не на число открытых вкладок, а на последствия: было ли проще закончить работу, находились ли нужные источники, не пропустилось ли действительно важное сообщение. Это проверка устройства потока, а не соревнование в самодисциплине.', 'imperial-future')),
            EditorialBlocks::paragraph(__('Подписки и привычки меняются вместе с задачами. То, что помогало изучать новый инструмент, может мешать после завершения проекта. Разреши себе пересматривать источники и оставлять время для чтения без немедленной практической цели. Спокойный телеграф не означает пустую ленту. Он означает, что важное, рабочее и просто интересное больше не требуют одинакового внимания.', 'imperial-future')),
        ]);
    }
}
